```scss
public Move alphaBetaFindBestMove(Game game, int depth, Player maxPlayer) {
    double alpha = Double.NEGATIVE_INFINITY;
    double beta = Double.POSITIVE_INFINITY;
    Move bestMove = null;

    for (Move move : game.getAllMoves(game.getCurrentPlayer())) {
        Game newGame = game.applyMove(move);
        double value = alphaBeta(new DFSTreeNode(newGame, maxPlayer), depth - 1, alpha, beta, false);

        if (value > alpha) {
            alpha = value;
            bestMove = move;
        }
    }

    return bestMove;
}

private double alphaBeta(DFSTreeNode node, int depth, double alpha, double beta, boolean isMaximizingPlayer) {
    if (depth == 0 || node.isTerminal()) {
        return node.getMaxPlayerUtilityValue();
    }

    double value = isMaximizingPlayer ? Double.NEGATIVE_INFINITY : Double.POSITIVE_INFINITY;
    for (DFSTreeNode child : node.getChildren()) {
        double childValue = alphaBeta(child, depth - 1, alpha, beta, !isMaximizingPlayer);
        value = isMaximizingPlayer ? Math.max(value, childValue) : Math.min(value, childValue);

        if (isMaximizingPlayer) {
            alpha = Math.max(alpha, value);
            if (beta <= alpha) {
                break;
            }
        } else {
            beta = Math.min(beta, value);
            if (beta <= alpha) {
                break;
            }
        }
    }

    return value;
}
```
